answers.body:
You're looking for OpenMP tasks , added in OpenMP 3: #include <stdio.h>
#include <omp.h>

void func1(int arg) {
    int tid = omp_get_thread_num();
    printf("Thread %d in func1: got arg %d\n", tid, arg);
}

void func2(int arg) {
    int tid = omp_get_thread_num();
    printf("Thread %d in func2: got arg %d\n", tid, arg);
}

void func3(int arg) {
    int tid = omp_get_thread_num();
    printf("Thread %d in func3: got arg %d\n", tid, arg);
}

int  main(int argc, char **argv) {
    int arg=173;
    #pragma omp parallel default(none) shared(arg) 
    #pragma omp single 
    {
        #pragma omp task
        func1(arg);

        #pragma omp task
        func2(arg);

        #pragma omp task
        func3(arg);

        #pragma omp taskwait
        /* if you have something that needs all the results above 
         * but needs to be in the parallel reason it would go here;
         * otherwise the task wait is not needed */
    }

    return 0;
} Running gives: $ export OMP_NUM_THREADS=3
$ ./tasks 
Thread 1 in func3: got arg 173
Thread 0 in func2: got arg 173
Thread 2 in func1: got arg 173 If for some reason (Visual Studio) you're stuck using OpenMP 2, you can use sections, which are less flexible but work fine here: int  main(int argc, char **argv) {
    int arg=173;
    #pragma omp parallel sections default(none) shared(arg)
    {
        func1(arg);

        #pragma omp section
        func2(arg);

        #pragma omp section
        func3(arg);
    }

    return 0;
}

