      {
        #pragma omp task firstprivate(t,i,j) depend(in:B[i-1:b+2][j-1:b+2]) depend(out:A[i:b][j:b])
        {
          #pragma omp critical  
          printf("t-%d i-%d j-%d --B",t,i,j);     //Prints out time loop, i,j 
