    double minimum = ::std::numeric_limits<double>::infinity();
    //#pragma omp parallel for // still broken
    for(int i = start; i < stop; i++){
        for(int j = start; j < stop; j++) {
            double temp = pow(((input[j][0]) - (input[i][0])), 2) + pow(((input[j][2]) - (input[i][3])), 2);
            temp = sqrt(temp);
            if(temp < minimum && i < j) minimum = temp;
        }
    }
    return minimum;
} A proper OMP minimum computation OMP has support for reductions , which will in all probability perform fairly well. To try it, we will use the following pragma, which ensures that each thread works on its own minimum variable which are combined using the minimum operator: #pragma omp parallel for reduction(min: minimum) The results validate the approach for ICC: Windows x64 with icc 14.0

0.0559233
622.1 ms But MSVC howls error C3036: 'min' : invalid operator token in OpenMP 'reduction' clause , because it does not support minimum reductions. To define our own reduction, we will use a technique called double-checked locking : double calcDistance(double input[][2], int start, int stop){
    double minimum = ::std::numeric_limits<double>::infinity();
    #pragma omp parallel for
    for(int i = start; i < stop; i++){
        for(int j = start; j < stop; j++) {
            double temp = pow(((input[j][0]) - (input[i][0])), 2) + pow(((input[j][1]) - (input[i][1])), 2);
            temp = sqrt(temp);
            if(temp < minimum && i < j)
            {
                #pragma omp critical
                if(temp < minimum && i < j) minimum = temp;
            }
        }
    }
    return minimum;
} This is not only correct, but also leads to comparable performance for MSVC (note that this is significantly faster than the incorrect version!): Windows x64 with msvc VS 2013 (18.00.21005)

