matplot(Y,type="l",lty=1)
matplot(Y_nonoise,type="l",add=TRUE, lwd=3, col=adjustcolor("blue",alpha.f=0.2),lty=1)
matplot(Y.fitted,type="l",add=TRUE, lwd=3, col=adjustcolor("red",alpha.f=0.2),lty=1) And now using Rcpp calling our R fitting function logconcobs within a #pragma openmp parallel for loop , enclosed with a #pragma omp critical : library(Rcpp)
