Rcpp::sourceCpp('fitMbycol.cpp')
microbenchmark(Y.fitted <- fitMbycol(Y, function (y) logconcobs(y, tau=0.5, nknots=10), nthreads=8L ), times=5L) # 361 ms OpenMP of course ends up not having any effect in this case, as the #pragma omp critical causes everything to execute sequentially, but in more complex examples this could still be useful.

