} And the CPU-Intensive work includes usage of OpenMP.  (Note, result is the same if I remove the schedule(static).) // Note: I shrunk these numbers down until the amount of work is actually
// small, not CPU-intensive at all, and it still hangs
static const int GlobalBufferChunkSize = 64;
static const int NumGlobalBufferChunks = 64;
static const int StrideSize = 16;
